    meaning: `After the light touches the great mountain of camphor Is there blackness of charcoal in that beautiful place? The true space of harmony lies in the unity of Shiva and Jiva (God and Soul) Knowing the stance (or: state), stand firm! – Muddu Rāma.`,
    themes: ["Devotion", "Divine", "Wonder", "Mind"]
