    meaning: `You seeing this flower that I grew in the garden, Do not ask, 'Which is beautiful to you?' In color, in fragrance, every single one is charming to me; Yours is your choice! – Dear Rāma.`,
    themes: ["Nature", "Beauty", "Joy", "Devotion"]
