    meaning: `What if someone praises? What if someone criticizes? You remain smiling in the world, like a wild flower. Does a flower bloom in the grove yearning for praise? Blooming is inevitable/necessary - Dear Rāma.`,
    themes: ["Nature", "Beauty", "Society", "Devotion"]
