    meaning: `For this celebration of life, how many star clusters, River channels, mountain ranges, the beautiful vastness of the sea! Like the rain of Shravana, new sprouts in Chaitra; With this much, what lack is there? – Dear Rāma.`,
    themes: ["Nature", "Beauty", "Life", "Devotion"]
