    meaning: `If you burn and rub sandalwood, is there fragrance? Where is the sweetness of joy in a forgotten love song? Where is the flower of consciousness for a vine whose roots have dried? There is no beauty in inertia – Dear Rāma.`,
    themes: ["Nature", "Beauty", "Love", "Devotion"]
