    meaning: `Let the compartments in the train of the heart be separate For reading, for singing, for eating and sleeping. Just as labor is for thought, so beauty is for joy! Fill life with movement – Muddu Rama.`,
    themes: ["Life", "Hope", "Love", "Nature"]
