    meaning: `Determination will not be achieved just by chanting a mantra; If you don't water the sapling, will you get a mango? Action is inevitable for inner blooming; Pour water for sprouting – Dear Rama.`,
    themes: ["Joy", "Life", "Mind", "Fate"]
