    meaning: `'Why need a sharpened, keen blade to kill those who love (you)? Is it not enough just to say, 'I do not want you'?' This is the commentary on affection for the confluence of throbbing hearts. Speech is the wave of the Ganga! – Muddu Rāma.`,
    themes: ["Love", "Life", "Beauty", "Mind"]
